ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  success: false,
  error: {
    code: "DUPLICATE_SKU",
    message: "No se permiten SKUs duplicados dentro de la misma orden.",
    httpStatus: 400,
    correlationId: vars.correlationId default correlationId
  }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
  success: false,
  error: {
    code: "VALIDATION_ERROR",
    message: "El producto solicitado esta inactivo: " ++ (vars.currentItemToValidate.sku default ""),
    httpStatus: 400,
    correlationId: vars.correlationId default correlationId
  }
}

%dw 2.0
output application/json
---
{
  success: false,
  error: {
    code: "INSUFFICIENT_STOCK",
    message: "Inventario insuficiente para el SKU: " ++ (vars.currentItemToValidate.sku default ""),
    httpStatus: 409,
    correlationId: vars.correlationId default correlationId
  }
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
payload ++ {
  message: "La orden ya se encuentra sincronizada con Salesforce."
}
